function rightSideView(root: TreeNode | null): number[] {
  const result: number[] = [];
  if (root === null) return result;

  // Обходим дерево по уровням, каждый уровень — слева направо
  let level: TreeNode[] = [root];

  while (level.length > 0) {
    // Справа виден последний узел уровня
    result.push(level[level.length - 1].val);

    // Собираем следующий уровень в том же порядке: слева направо
    const next: TreeNode[] = [];
    for (const node of level) {
      if (node.left !== null) next.push(node.left);
      if (node.right !== null) next.push(node.right);
    }
    level = next;
  }

  return result;
}

// Время: O(n) — каждый узел обрабатывается один раз
// Память: O(w) — максимальная ширина уровня
